// Message automatique (réponse d'absence, notification, adresse « noreply ») : ignoré, sans appel à l'IA.
function estAutomatique(m) {
  const h = Object.fromEntries(Object.entries(m.entetes || {}).map(([k, v]) => [String(k).toLowerCase(), String(v)]));
  return /auto-(replied|generated)/i.test(h['auto-submitted'] || '') || Boolean(h['x-autoreply']) || Boolean(h['x-autorespond']) ||
    /^(réponse automatique|automatic reply|auto(matic)?[- ]reply|out of office|absence)/i.test(String(m.sujet || '').trim()) ||
    /(no-?reply|mailer-daemon|postmaster)@/i.test(String(m.de_email || ''));
}

function preparerDemande(m, parent, demandeId, demandeParente, R) {
  const chat = m.canal === 'chat';
  const emailReponse = String(chat ? (m.chat && m.chat.email) : m.de_email || '').trim().toLowerCase();
  const demande = {
    demande_id: parent ? parent.demande_id : demandeId,
    canal: chat ? 'chat' : 'email',
    recue_le: m.recu_le,
    message_id: m.message_id || '',
    de_email: emailReponse,
    de_nom: m.de_nom || '',
    sujet: m.sujet || (chat ? 'Chat du site' : ''),
    texte: String(m.texte || '').slice(0, 5000),
    automatique: !chat && estAutomatique(m),
    parent: parent || null,
    demande_parente: demandeParente || '',
    email_reponse: emailReponse,
    numero_saisi: chat ? String((m.chat && m.chat.numero_commande) || '').replace(/\D/g, '') || null : null,
  };
  const L = lectureMessage(R);
  const contexte = parent
    ? L.contexte + " ; c'est la réponse d'un client à qui l'on a demandé de préciser de quelle commande il parle ; " +
      "s'il désigne une commande, c'est une demande de suivi (commandes en cours : n° " + parent.candidats.join(', n° ') + ')'
    : L.contexte;
  return {
    demande,
    texte: demande.texte,
    meta: { from: (demande.de_nom ? demande.de_nom + ' ' : '') + '<' + demande.de_email + '>', subject: demande.sujet },
    schema: L.schema,
