const STATUTS_EN_COURS = ['pending', 'on-hold', 'processing'];
const memeEmail = (a, b) => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase();
const metaCommande = (o, cle) => (cle ? ((o.meta_data || []).find(m => m.key === cle) || {}).value || '' : '');

// Numéro de suivi, transporteur et date d'expédition : champs personnalisés choisis dans « Vos réglages »,
// sinon ceux de l'extension « Advanced Shipment Tracking » (_wc_shipment_tracking_items).
function infosColis(o, R) {
  const ast = metaCommande(o, '_wc_shipment_tracking_items');
  const t = Array.isArray(ast) && ast.length ? ast[ast.length - 1] : null;
  const date = t && t.date_shipped ? (isFinite(Number(t.date_shipped)) ? new Date(Number(t.date_shipped) * 1000).toISOString() : String(t.date_shipped)) : '';
  return {
    numero: String(metaCommande(o, R.champ_numero_suivi) || (t && t.tracking_number) || ''),
