}

// Situation à partir du statut WooCommerce et, si vous l'avez branché, du suivi transporteur.
function situationCommande(o, suivi, R) {
  const s = o.status;
  const numero = infosColis(o, R).numero;
  if (s === 'pending' || s === 'on-hold') return 'en attente de paiement';
  if (s === 'cancelled' || s === 'failed') return 'annulée';
  if (s === 'refunded') return 'remboursée';
  if (s === 'processing') return numero ? 'expédiée' : 'en préparation';
  if (!suivi) return numero ? 'expédiée' : 'en préparation';
  return {
    ANNONCE: 'expédiée', PRIS_EN_CHARGE: 'expédiée',
    EN_TRANSIT: 'en transit', ARRIVE_AGENCE: 'en transit',
    RETARD: 'retard',
    EN_LIVRAISON: 'en cours de livraison',
    AVIS_PASSAGE: 'en point relais', DISPONIBLE_RELAIS: 'en point relais',
