// Après WooCommerce : commandes candidates et numéros de suivi à interroger.
// reponse : réponse complète du nœud HTTP ({ statusCode, body }).
function analyserCommandes(entree, reponse, R, maintenantMs) {
  const email = entree.email;
  let etat, candidates = [], commande_id = null;
  if (entree.numero) {
    const o = reponse && reponse.statusCode === 200 && reponse.body && !Array.isArray(reponse.body) ? reponse.body : null;
    if (!o) etat = 'introuvable';
    else if (!memeEmail(o.billing && o.billing.email, email)) { etat = 'autre_client'; commande_id = o.id; }
    else { etat = 'trouvee'; candidates = [o]; }
  } else {
    const liste = reponse && reponse.statusCode === 200 && Array.isArray(reponse.body) ? reponse.body : [];
    const limite = maintenantMs - entree.jours_en_cours * 86400000;
    candidates = liste
      .filter(o => memeEmail(o.billing && o.billing.email, email))
      .filter(o => !entree.candidats_autorises || entree.candidats_autorises.map(String).includes(String(o.id)))
      .filter(o => STATUTS_EN_COURS.includes(o.status) ||
        (o.status === 'completed' && infosColis(o, R).numero && Date.parse(infosColis(o, R).expedie_le || o.date_created) >= limite));
    etat = candidates.length ? 'a_confirmer' : 'aucune';
  }
  const suivis = candidates.map(o => infosColis(o, R).numero).filter(Boolean);
  return { etat, commande_id, candidates, suivis };
}

// Ce que l'on garde d'une commande (jamais d'adresse complète ni de téléphone).
function instantane(o, suivi, R) {
