    dernier_evenement: (suivi.evenements || [])[0] || null,
  } : (c.numero ? { transporteur: c.transporteur, numero: c.numero, statut: 'INCONNU' } : null);
  return {
    commande: {
      id: o.id, statut_woo: o.status, date: o.date_created, total: o.total,
