function conclureRecherche(entree, analyse, suivis, R) {
  const parNumero = {};
  for (const s of suivis || []) if (s && s.numero) parNumero[String(s.numero)] = s;
  const suiviDe = o => parNumero[infosColis(o, R).numero] || null;
  const vide = { candidates: [], situation: null, commande: null, colis: null };
  if (['introuvable', 'autre_client', 'aucune'].includes(analyse.etat)) return { etat: analyse.etat, commande_id: analyse.commande_id, ...vide };
