// Les règles décident (regles.js), vos modèles répondent (modeles.js). L'IA n'écrit aucune phrase.
// Les règles de décision (regles-de-decision.md) : écrites à l'avance, lues dans l'ordre, la première qui
// s'applique décide. L'IA n'a fourni que l'intention et le numéro de commande ; tout le reste vient des données.
// Une valeur absente mène toujours au transfert, jamais à une réponse devinée.

const SITUATIONS_AUTO = ['en préparation', 'expédiée', 'en transit', 'en cours de livraison', 'retard', 'en point relais'];
const codeSituation = s => 'situation_' + String(s).replace(/ /g, '_').normalize('NFD').replace(/[̀-ͯ]/g, '');

// Dans une réponse à une demande de précision, le client ne fait que désigner sa commande.
function intentionRetenue(demande, lecture) {
  const i = lecture && lecture.champs ? lecture.champs.intention : null;
  if (demande.parent && (i === null || i === 'autre' || i === 'suivi')) return 'suivi';
  return i;
}

function decider(demande, lecture, recherche, seuil) {
  const r = (decision, raison, extra = {}) => ({ decision, raison, situation: null, commande_id: null, ...extra });
  // 1. Message automatique (absence, notification) : ignoré, sans IA
  if (demande.automatique) return r('ignorer', 'automatique');
  const intention = intentionRetenue(demande, lecture);
  // 2. Message illisible ou intention non justifiée par une phrase du client
  if (!lecture || !lecture.lisible || Number(lecture.confiance) < Number(seuil) || !intention) return r('transférer', 'illisible');
  // 3. Un retour, un échange, un remboursement
  if (intention === 'retour') return r('transférer', 'retour', { commande_id: recherche && recherche.commande_id });
  // 4. Un autre sujet, ou plusieurs sujets à la fois
  if (intention !== 'suivi') return r('transférer', 'hors_suivi', { commande_id: recherche && recherche.commande_id });
  if (!recherche) return r('transférer', 'illisible');
  const ancre = { commande_id: recherche.commande_id };
  // 5. Numéro de commande introuvable
  if (recherche.etat === 'introuvable') return r('transférer', 'commande_introuvable');
  // 6. La commande d'un autre client (e-mail différent) : accusé neutre, aucune information donnée
  if (recherche.etat === 'autre_client') return r('transférer', 'commande_autre_client', ancre);
  // 7. Une précision demandée, mais la réponse ne désigne pas une commande
  if (demande.parent && recherche.etat !== 'trouvee') return r('transférer', 'precision_sans_reponse');
  // 8. Aucune commande en cours à cette adresse
  if (recherche.etat === 'aucune') return r('transférer', 'aucune_commande');
  // 9. Plusieurs commandes en cours et pas de numéro : on demande laquelle
  if (recherche.etat === 'plusieurs') return r('préciser', 'plusieurs_commandes');
  // 10. Colis livré, incident, commande annulée, en attente de paiement… : un humain
  if (!SITUATIONS_AUTO.includes(recherche.situation)) {
    return r('transférer', codeSituation(recherche.situation), { ...ancre, situation: recherche.situation });
  }
  // Seulement si tout est clair : la réponse automatique
  return r('répondre', 'suivi_nominal', { ...ancre, situation: recherche.situation });
}
