const MODELES = Object.assign({}, M.reponses, M.precision, M.accuses, M.brouillons);

const ACCUSE = { retour: 'accuse_retour', commande_autre_client: 'accuse_neutre', commande_introuvable: 'accuse_neutre' };
const BROUILLON = { retour: 'brouillon_retour', situation_livree: 'brouillon_livree', situation_incident: 'brouillon_incident' };
const REPONSE = {
  'en préparation': 'en_preparation', 'expédiée': 'expediee', 'en transit': 'en_transit',
  'en cours de livraison': 'en_livraison', 'retard': 'retard', 'en point relais': 'point_relais',
};

const dateFr = iso => {
  if (!iso) return '';
  const d = DateTime.fromISO(String(iso), { zone: 'Europe/Paris' }).setLocale('fr');
  return d.isValid ? d.toFormat('cccc d LLLL') : '';
};
const jourRelatif = iso => {
  if (!iso) return '';
  const d = DateTime.fromISO(String(iso), { zone: 'Europe/Paris' }).startOf('day');
  if (!d.isValid) return '';
  const ecart = Math.round(d.diff(DateTime.now().setZone('Europe/Paris').startOf('day'), 'days').days);
  return ({ '-1': 'hier', 0: "aujourd'hui", 1: 'demain' })[ecart] || 'le ' + dateFr(iso);
};

// Messages à rédiger pour une décision : la réponse (ou la demande de précision, ou l'accusé de réception),
// plus, pour un transfert, le brouillon préparé pour vous.
function messagesPour(decision, d, recherche, lecture, R) {
  const chat = d.canal === 'chat';
  const cmd = recherche && recherche.commande;
  const colis = recherche && recherche.colis;
  const ev = colis && colis.dernier_evenement;
  const prenom = (cmd && cmd.prenom) || String((lecture && lecture.champs && lecture.champs.nom) || d.de_nom || '').split(/\s+/)[0] || '';
  const numeroSuivi = (colis && colis.numero) || '';
  const v = {
    bonjour: prenom ? 'Bonjour ' + prenom : 'Bonjour',
    numero: cmd ? String(cmd.id) : (decision.commande_id ? String(decision.commande_id) : ''),
    date_commande: cmd ? dateFr(cmd.date) : '',
    articles: cmd ? cmd.articles.map(a => a.quantite + ' × ' + a.nom).join(', ') : '',
    articles_ou_article: cmd ? cmd.articles.map(a => a.nom).join(', ') : "l'article",
    ville: (cmd && cmd.livraison_ville) || 'votre adresse',
    transporteur: (colis && colis.transporteur) || 'le transporteur',
    numero_suivi: numeroSuivi,
    lien_suivi: numeroSuivi && R.lien_suivi
      ? String(R.lien_suivi).replace('{numero}', encodeURIComponent(numeroSuivi)).replace('{transporteur}', encodeURIComponent((colis && colis.transporteur) || ''))
      : '',
    date_expedition: cmd && cmd.expediee_le ? jourRelatif(cmd.expediee_le) || 'récemment' : 'récemment',
    date_estimee: colis && colis.date_estimee ? jourRelatif(colis.date_estimee) || 'prochainement' : 'prochainement',
    date_estimee_initiale: colis && colis.date_estimee_initiale ? jourRelatif(colis.date_estimee_initiale) || 'initialement' : 'initialement',
    derniere_etape: ev && ev.libelle ? ev.libelle.charAt(0).toLowerCase() + ev.libelle.slice(1) : 'colis pris en charge',
    date_etape: ev ? jourRelatif(ev.date) || 'récemment' : 'récemment',
    liste: ((recherche && recherche.candidates) || []).map(c => '- n° ' + c.id + ' du ' + dateFr(c.date) + ' (' + String(c.total).replace('.', ',') + ' €)').join('\n'),
    liste_courte: ((recherche && recherche.candidates) || []).map(c => 'n° ' + c.id).join(', '),
    delai_retour: String(R.delai_retour_jours || '14'),
    objet_libre: d.sujet ? 'Re: ' + d.sujet.replace(/\s*\[REF [^\]]+\]/g, '') : 'Votre message',
  };
  const un = (type, cle) => {
    const m = MODELES[cle];
    const texte = chat && m.chat && type !== 'brouillon' ? m.chat : m.email + '\n\n' + R.signature;
    return { type, cle, modele: texte, sujet: m.objet + ' [REF ' + d.demande_id + ']', variables: v };
  };
  if (decision.decision === 'répondre') return [un('réponse', REPONSE[decision.situation])];
  if (decision.decision === 'préciser') return [un('précision', 'precision')];
  if (decision.decision === 'transférer') {
    return [un('accusé', ACCUSE[decision.raison] || 'accuse'), un('brouillon', BROUILLON[decision.raison] || 'brouillon_libre')];
  }
  return [];
}

// Remplit un modèle. Une variable vide bloque l'envoi : la demande passe alors à un humain.
function rediger(m, destinataire) {
  const manquantes = new Set();
  const remplir = t => String(t || '').replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, cle) => {
    const x = m.variables[cle];
    if (x === undefined || x === null || x === '') { manquantes.add(cle); return ''; }
    return String(x);
  });
  const echapper = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const sujet = remplir(m.sujet);
  const corps = remplir(m.modele);
  const html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5;color:#1f2933">' +
    echapper(corps).split(/\n{2,}/).map(p => '<p style="margin:0 0 14px">' + p
      .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" style="color:#0f5e8c;font-weight:600">$1</a>')
      .replace(/\n/g, '<br>') + '</p>').join('') + '</div>';
  const erreurs = [];
  if (manquantes.size) erreurs.push('variables vides : ' + [...manquantes].join(', '));
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(destinataire || ''))) erreurs.push('destinataire invalide');
  return {
    type: m.type, modele: m.cle, sujet, html, erreurs,
    corps: corps.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '$1 : $2'),
    pret: erreurs.length === 0,
  };
}
const d = $('Contexte de la demande').first().json.demande;
const R = $('Vos réglages').first().json;
const lecture = $('Contrôler la lecture').isExecuted ? $('Contrôler la lecture').first().json : null;
const recherche = $('Conclure').isExecuted ? $('Conclure').first().json : null;
const decision = decider(d, lecture, recherche, R.seuil_confiance);
const messages = messagesPour(decision, d, recherche, lecture, R).map(m => rediger(m, d.email_reponse));
const principal = messages.find(m => m.type !== 'brouillon') || null;
const brouillon = messages.find(m => m.type === 'brouillon') || null;
const envoyer = Boolean(principal && principal.pret && d.canal === 'email');
return [{ json: { decision, principal, brouillon, envoyer, destinataire: d.email_reponse } }];

// Statut : ignorée | répondue (auto) | précision demandée | à traiter. Pour « à traiter », le brouillon est dans la
// colonne « brouillon » : relisez-le, complétez-le et collez votre texte dans « votre_reponse » (workflow 04).
// Tableur Google Sheets : onglets « Demandes » et « Échanges » (colonnes : dossier tableur/ du dépôt).
const ENTETES = {"Demandes": ["demande_id", "recue_le", "canal", "de_email", "de_nom", "sujet", "texte", "statut", "decision", "raison", "intention", "citation_intention", "numero_commande", "commande_id", "situation", "brouillon", "votre_reponse", "repondu_le", "repondu_par", "confiance", "contexte", "message_id", "demande_parente", "maj_le"], "Échanges": ["echange_id", "demande_id", "sens", "type", "statut", "sujet", "corps", "cree_le", "envoye_le", "message_id"]};
const ZONE = 'Europe/Paris';
const horodatage = () => DateTime.now().setZone(ZONE).toISO({ suppressMilliseconds: true });

// Identifiant court et horodaté, sans collision entre exécutions parallèles (D… demande, E… échange).
function nouvelId(prefixe) {
  return prefixe + Date.now().toString(36).toUpperCase().slice(-6) + Math.random().toString(36).slice(2, 4).toUpperCase();
}

// Lit la réponse d'un values:batchGet en { Onglet: [ { colonne: valeur, row_number } ] }.
function lirePlages(reponse) {
  const out = {};
  for (const plage of (reponse.valueRanges || [])) {
    const onglet = plage.range.split('!')[0].replace(/^'|'$/g, '');
    const [entetes = [], ...lignes] = plage.values || [];
    out[onglet] = lignes.map((l, i) => Object.assign(
      Object.fromEntries(entetes.map((c, j) => [c, l[j] === undefined ? '' : l[j]])), { row_number: i + 2 }));
  }
  return out;
}

// Écritures en requêtes de l'API Sheets : ajouts par values:append (pas de collision entre exécutions),
// mises à jour cellule par cellule (on n'écrase jamais une colonne que vous avez remplie entre-temps).
function requetesTableur(idTableur, appends, updates) {
  const valeur = v => (v === null || v === undefined ? '' : typeof v === 'object' ? JSON.stringify(v) : v);
  const lettre = i => { let s = ''; for (let n = i + 1; n > 0; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s; return s; };
  const base = 'https://sheets.googleapis.com/v4/spreadsheets/' + idTableur;
  const requetes = [];
  for (const [onglet, lignes] of Object.entries(appends || {})) {
    if (!lignes || !lignes.length) continue;
    requetes.push({
      url: base + '/values/' + encodeURIComponent("'" + onglet + "'!A1") + ':append?valueInputOption=RAW&insertDataOption=INSERT_ROWS',
      body: { values: lignes.map(l => ENTETES[onglet].map(c => valeur(l[c]))) },
    });
  }
  const data = [];
  for (const u of updates || []) {
    for (const [col, v] of Object.entries(u.champs || {})) {
      const j = ENTETES[u.onglet].indexOf(col);
      if (j < 0) throw new Error('Colonne inconnue : ' + u.onglet + '.' + col);
      data.push({ range: "'" + u.onglet + "'!" + lettre(j) + u.row_number, values: [[valeur(v)]] });
    }
  }
  if (data.length) requetes.push({ url: base + '/values:batchUpdate', body: { valueInputOption: 'RAW', data } });
  return requetes;
}
const d = $('Contexte de la demande').first().json.demande;
const R = $('Vos réglages').first().json;
const { decision, principal, brouillon } = $('Décider').first().json;
const lecture = $('Contrôler la lecture').isExecuted ? $('Contrôler la lecture').first().json : null;
const recherche = $('Conclure').isExecuted ? $('Conclure').first().json : null;
const envoye = $("Envoyer l'e-mail").isExecuted;
const chat = d.canal === 'chat';
const now = horodatage();

const parti = Boolean(principal && principal.pret && (chat || envoye));
let statut = 'à traiter', raison = decision.raison;
if (decision.decision === 'ignorer') statut = 'ignorée';
else if (decision.decision === 'répondre') statut = parti ? 'répondue (auto)' : 'à traiter';
else if (decision.decision === 'préciser') statut = parti ? 'précision demandée' : 'à traiter';
if (['répondre', 'préciser'].includes(decision.decision) && !parti) raison = 'envoi_bloque';
const auto = ['répondre', 'préciser'].includes(decision.decision) && parti;

const trouvee = recherche && recherche.etat === 'trouvee';
const champs = {
  intention: lecture ? lecture.champs.intention || '' : '',
  citation_intention: lecture ? lecture.citations.intention || '' : '',
  numero_commande: d.numero_saisi || (lecture && lecture.champs.numero_commande) || '',
  commande_id: decision.commande_id || '',
  situation: decision.situation || '',
  decision: decision.decision,
  raison,
  statut,
  brouillon: brouillon ? brouillon.corps : '',
  confiance: lecture ? lecture.confiance : '',
  contexte: {
    etat_recherche: recherche ? recherche.etat : null,
    commande: trouvee ? recherche.commande : null,
    colis: trouvee ? recherche.colis : null,
    candidates: recherche && recherche.etat === 'plusieurs' ? recherche.candidates : [],
    resume: lecture ? lecture.champs.resume : null,
  },
  maj_le: now,
};

const appends = { Demandes: [], 'Échanges': [] };
const updates = [];
if (d.parent) {
  // La demande en précision continue : la date de première réponse automatique est conservée.
  updates.push({ onglet: 'Demandes', row_number: d.parent.row_number, champs });
} else {
  appends.Demandes.push({
    demande_id: d.demande_id, recue_le: d.recue_le, canal: d.canal, de_email: d.de_email,
    de_nom: d.de_nom || (lecture && lecture.champs.nom) || '', sujet: d.sujet, texte: d.texte, ...champs,
    repondu_le: auto ? now : '', repondu_par: auto ? 'auto' : '', message_id: d.message_id, demande_parente: d.demande_parente,
  });
}
appends['Échanges'].push({ echange_id: nouvelId('E'), demande_id: d.demande_id, sens: 'entrant', type: 'message', statut: 'reçu',
  sujet: d.sujet, corps: d.texte, cree_le: d.recue_le, envoye_le: '', message_id: d.message_id });
if (principal) {
  appends['Échanges'].push({ echange_id: nouvelId('E'), demande_id: d.demande_id, sens: 'sortant', type: principal.type,
    statut: !principal.pret ? 'bloqué (' + principal.erreurs.join(', ') + ')' : chat ? 'affiché' : envoye ? 'envoyé' : 'bloqué',
    sujet: principal.sujet, corps: principal.corps, cree_le: now, envoye_le: parti ? now : '',
    message_id: envoye ? $("Envoyer l'e-mail").first().json.messageId || '' : '' });
}
if (brouillon) {
  appends['Échanges'].push({ echange_id: nouvelId('E'), demande_id: d.demande_id, sens: 'sortant', type: 'brouillon',
    statut: 'en attente de validation', sujet: brouillon.sujet, corps: brouillon.corps, cree_le: now, envoye_le: '', message_id: '' });
}
return [{ json: {
  requetes: requetesTableur(R.id_tableur, appends, updates),
  resultat: { demande_id: d.demande_id, canal: d.canal, decision: decision.decision, raison, statut,
    reponse_chat: chat && parti ? principal.corps : null },
} }];
